package com.hbm.machine.radar;
import api.hbm.entity.RadarEntry;import java.util.*;import java.util.function.Consumer;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.server.level.ServerLevel;import net.neoforged.neoforge.network.PacketDistributor;import net.neoforged.neoforge.network.event.RegisterPayloadHandlersEvent;
/** Original actual radar state and only100map bytes each tick, never a40000-byte map retransmission everytick. */
public record RadarStatePacket(BlockPos position,long power,int maxPower,int range,int consumption,int flags,List<RadarEntry> entries,int mapIndex,byte[] map)implements CustomPacketPayload{public static Consumer<RadarStatePacket> CLIENT=p->{};public static final Type<RadarStatePacket> TYPE=new Type<>(RadarContent.id("radar_state"));public static final StreamCodec<RegistryFriendlyByteBuf,RadarStatePacket> CODEC=StreamCodec.of((b,p)->{b.writeBlockPos(p.position);b.writeLong(p.power);b.writeInt(p.maxPower);b.writeInt(p.range);b.writeInt(p.consumption);b.writeInt(p.flags);b.writeVarInt(p.entries.size());for(var e:p.entries)e.write(b);b.writeShort(p.mapIndex);if(p.mapIndex>=0)b.writeBytes(p.map);},b->{var pos=b.readBlockPos();long power=b.readLong();int max=b.readInt(),range=b.readInt(),cons=b.readInt(),flags=b.readInt(),count=b.readVarInt();var list=new ArrayList<RadarEntry>();for(int i=0;i<count;i++)list.add(RadarEntry.read(b));int index=b.readShort();byte[] map=index>=0?new byte[100]:new byte[0];if(index>=0)b.readBytes(map);return new RadarStatePacket(pos,power,max,range,cons,flags,list,index,map);});@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}public static void register(RegisterPayloadHandlersEvent e){e.registrar("1").playToClient(TYPE,CODEC,(p,c)->c.enqueueWork(()->CLIENT.accept(p)));}public static void send(ServerLevel server,RadarBlockEntity radar,int radius){int flags=(radar.scanMissiles?1:0)|(radar.scanShells?2:0)|(radar.scanPlayers?4:0)|(radar.smartMode?8:0)|(radar.redMode?16:0)|(radar.showMap?32:0)|(radar.jammed?64:0)|(radar.clearFlag?128:0);int index=radar.showMap&&!radar.clearFlag?(int)(server.getGameTime()%400):-1;byte[] bytes=index>=0?Arrays.copyOfRange(radar.map,index*100,index*100+100):new byte[0];var packet=new RadarStatePacket(radar.getBlockPos(),radar.power,RadarConfig.maxPower,radar.range(),RadarConfig.consumption,flags,List.copyOf(radar.entries),index,bytes);for(var player:server.players())if(player.distanceToSqr(radar.getBlockPos().getX(),radar.getBlockPos().getY(),radar.getBlockPos().getZ())<radius*radius)PacketDistributor.sendToPlayer(player,packet);}}
